            raise ValueError('桥接对必须指向两个不同的EEG通道')
        for i in pair:
            _integer(i, 'bridged_idx')
    if p['bridged_idx']:
        y = mne.preprocessing.interpolate_bridged_electrodes(y, **p)
    return _out(y, pairs=p['bridged_idx'], before=before)

