# Extensions for the frozen MNE 1.10.2 / PyPREP 0.7.1 contracts.
import copy as _core_copylib
import hashlib as _core_hashlib
import importlib.metadata as _core_metadata
import warnings as _core_warnings
import json as _core_json
import numpy as np
import mne

def _core_kwargs(p, defaults, required=()):
    missing=set(required)-set(p);unknown=set(p)-set(defaults)
    if missing or unknown:raise ValueError('missing parameters='+str(sorted(missing))+'; unknown='+str(sorted(unknown)))
    return dict(defaults,**p)

def _core_bool(value,name):
    if not isinstance(value,(bool,np.bool_)):raise TypeError(name+' must be boolean')
    return bool(value)

def _core_int(value,name,low=0,high=None):
    if isinstance(value,(bool,np.bool_)) or not isinstance(value,(int,np.integer)) or value<low or (high is not None and value>high):raise ValueError(name+' invalid integer')
    return int(value)

def _core_real(value,name,low=None,high=None,strict=False):
    if isinstance(value,(bool,np.bool_)) or not isinstance(value,(int,float,np.integer,np.floating)) or not np.isfinite(value):raise ValueError(name+' must be finite real')
    if low is not None and (value<=low if strict else value<low):raise ValueError(name+' below range')
    if high is not None and value>high:raise ValueError(name+' above range')
    return float(value)

def _core_raw(x,allow_nan=False,epochs=False):
    if not isinstance(x,(mne.io.BaseRaw,mne.BaseEpochs) if epochs else mne.io.BaseRaw):raise TypeError('expected '+('Raw/Epochs' if epochs else 'Raw'))
    if isinstance(x,mne.BaseEpochs) and not x.preload:raise ValueError('Epochs must be preloaded')
    y=x.copy().load_data();a=y.get_data()
    if not a.size or np.iscomplexobj(a) or np.isinf(a).any() or (not allow_nan and np.isnan(a).any()):raise ValueError('empty, complex or unsupported nonfinite signal')
    return y

def _core_names(y,names,allow_empty=False):
    if not isinstance(names,(list,tuple)) or (not names and not allow_empty) or any(not isinstance(n,str) for n in names) or len(set(names))!=len(names):raise ValueError('channel names must be unique')
    good={n for n,t in zip(y.ch_names,y.get_channel_types()) if t=='eeg'}
    if not set(names)<=good:raise ValueError('existing EEG names required')
    return [y.ch_names.index(n) for n in names]

def _core_array_hash(a):
    a=np.ascontiguousarray(a)
    return _core_hashlib.sha256(str((a.dtype.str,a.shape)).encode()+a.tobytes()).hexdigest()

def _core_frame(y):
    return {'sfreq':float(y.info['sfreq']),'n_times':len(y.times),
            'first_samp':int(y.first_samp) if isinstance(y,mne.io.BaseRaw) else None,
            'epoch_selection':None if isinstance(y,mne.io.BaseRaw) else y.selection.tolist(),
            'epoch_events':None if isinstance(y,mne.io.BaseRaw) else y.events.tolist(),
            'tmin':float(y.times[0]),'meas_date':str(y.info.get('meas_date'))}

def _core_raw_hash(y):
    return _core_value_hash({'frame':_core_frame(y),'names':y.ch_names,'types':y.get_channel_types(),
        'bads':y.info['bads'],'data':y.get_data(),'locs':[c['loc'] for c in y.info['chs']],
        'dig':y.info['dig'],'projs':[dict(v) for v in y.info['projs']],
        'custom_ref_applied':int(y.info['custom_ref_applied']),
        'highpass':y.info['highpass'],'lowpass':y.info['lowpass'],
        'annotations':None if y.annotations is None else {'onset':y.annotations.onset,'duration':y.annotations.duration,
            'description':y.annotations.description,'ch_names':y.annotations.ch_names,
            'orig_time':str(y.annotations.orig_time)}})

def _core_value_hash(v):
    def plain(a):
        if isinstance(a,np.ndarray):
            if a.dtype.kind=='O':return {'shape':list(a.shape),'values':plain(a.tolist())}
            return {'dtype':a.dtype.str,'shape':list(a.shape),'hash':_core_array_hash(a)}
        if isinstance(a,np.generic):return plain(a.item())
        if isinstance(a,dict):return {str(k):plain(v) for k,v in a.items()}
        if isinstance(a,(list,tuple)):return [plain(v) for v in a]
        if isinstance(a,(str,int,float,bool)) or a is None:return a
        raise TypeError('unsupported state value: '+str(type(a)))
    return _core_hashlib.sha256(_core_json.dumps(plain(v),sort_keys=True,separators=(',',':'),allow_nan=True).encode()).hexdigest()

def _core_out(data,model=None,**artifacts):
    return {'data':data,'model':model,'artifacts':artifacts}

def _core_rng_dump(rng):
    name,keys,pos,has,cached=rng.get_state()
    return {'bit_generator':name,'keys':keys.copy(),'pos':int(pos),'has_gauss':int(has),'cached_gaussian':float(cached)}

def _core_rng(value):
    if value is None:
        rng=np.random.RandomState();rng.set_state(np.random.get_state());return rng
    if isinstance(value,(int,np.integer)) and not isinstance(value,(bool,np.bool_)):
        return np.random.RandomState(_core_int(value,'random_state',0,2**32-1))
    if not isinstance(value,dict) or set(value)!={'bit_generator','keys','pos','has_gauss','cached_gaussian'} or value['bit_generator']!='MT19937':raise ValueError('random_state must be None, uint32 seed, or MT19937 state')
    keys=np.asarray(value['keys'])
    if keys.shape!=(624,) or keys.dtype.kind not in 'iu' or np.any(keys<0) or np.any(keys>2**32-1):raise ValueError('invalid MT19937 keys')
    pos=_core_int(value['pos'],'pos',0,624);has=_core_int(value['has_gauss'],'has_gauss',0,1);cached=_core_real(value['cached_gaussian'],'cached_gaussian')
    rng=np.random.RandomState();rng.set_state(('MT19937',keys.astype(np.uint32),pos,has,cached));return rng

def _core_versions():
    if _core_metadata.version('pyprep')!='0.7.1' or mne.__version__!='1.10.2':raise RuntimeError('profile requires PyPREP 0.7.1 and MNE 1.10.2')

def _core_nonfinite_policy(value):
    if value not in ('reject','propagate'):raise ValueError('nonfinite must be reject or propagate')
    return value=='propagate'

# Author Reference phases, with read-only loop observations and explicit state.
import inspect as _core_inspect
import textwrap as _core_textwrap
from pathlib import Path as _CorePath
import pyprep.reference as _core_reference_module

_CORE_REFERENCE_SOURCE_SHA256='893ad8dbc7110a6ec3a2fa84da1330f1ebc990babd730c01742a719e3a1a0074'

class _CoreObservedReference(_core_reference_module.Reference):
    def _core_loop_start(self,loc):
        self._core_pending={'iteration':int(loc['iterations']),
            'rng_before':_core_rng_dump(self.random_state),
            'reference_before_V':self.reference_signal.copy(),
            'original_detrended_hash':_core_array_hash(loc['signal']),
            'detection_input_hash':_core_array_hash(loc['signal_tmp'])}

    def _core_loop_decision(self,loc):
        i=loc['iterations'];b=loc['bad_chans'];previous=loc['previous_bads']
        stable=i>1 and (len(b)==0 or b==previous);limited=i>loc['max_iterations']
        self._core_pending.update(rng_after=_core_rng_dump(self.random_state),
            detected=_core_copylib.deepcopy(loc['noisy_new']),
            accumulated=_core_copylib.deepcopy(loc['noisy']),
            reference_donors=list(loc['reference_channels']),reference_targets=list(loc['reference_channels']),
            stop=bool(stable or limited),stop_reason='stable' if stable else ('iteration_limit' if limited else None))
        self._core_trace.append(self._core_pending)

    def _core_loop_updated(self,loc):
        self._core_trace[-1].update(reference_after_V=self.reference_signal.copy(),
            reference_input_hash=_core_array_hash(loc['raw_tmp'].get_data()),
            next_detection_input_hash=_core_array_hash(loc['signal_tmp']))

def _core_observed_reference():
    _core_versions()
    path=_CorePath(_core_reference_module.__file__)
    if _core_hashlib.sha256(path.read_bytes()).hexdigest()!=_CORE_REFERENCE_SOURCE_SHA256:raise RuntimeError('author reference source changed')
    source=_core_textwrap.dedent(_core_inspect.getsource(_core_reference_module.Reference.robust_reference))
    changes={
        '    while True:\n':'    while True:\n        self._core_loop_start(locals())\n',
        '        if (\n            iterations > 1\n':'        self._core_loop_decision(locals())\n        if (\n            iterations > 1\n',
        '        iterations = iterations + 1\n':'        self._core_loop_updated(locals())\n        iterations = iterations + 1\n'}
    for old,new in changes.items():
        if source.count(old)!=1:raise RuntimeError('author loop observation anchor changed')
        source=source.replace(old,new)
    namespace=dict(vars(_core_reference_module));exec(compile(source,str(path)+':observed','exec'),namespace)
    _CoreObservedReference.robust_reference=namespace['robust_reference']
    return _CoreObservedReference

def _core_reference_model(ref,stage):
    state={k:_core_copylib.deepcopy(v) for k,v in ref.__dict__.items()
           if k not in ('raw','random_state','_core_pending')}
    state['random_state']=_core_rng_dump(ref.random_state)
    model={'kind':'eeg_prep_reference_071_v1','stage':stage,'state':state,
        'data_hash':_core_raw_hash(ref.raw),'author_source_sha256':_CORE_REFERENCE_SOURCE_SHA256}
    model['state_hash']=_core_value_hash(model)
    return model

def eeg_robust_reference(op,x,model=None,**p):
    _core_versions()
    if op=='prep_reference_fit':
        if model is not None:raise ValueError('fit requires model=None')
        p=_core_kwargs(p,{'ref_chs':None,'reref_chs':None,'max_iterations':4,'ransac':True,
            'channel_wise':False,'max_chunk_size':None,'random_state':None,'reject_by_annotation':None},('ref_chs','reref_chs'))
        y=_core_raw(x,allow_nan=True)
        if any(t!='eeg' for t in y.get_channel_types()):raise ValueError('reference state requires EEG-only Raw; partition auxiliary channels upstream')
        _core_names(y,p['ref_chs']);_core_names(y,p['reref_chs'])
        _core_int(p['max_iterations'],'max_iterations',0)
        for k in ('ransac','channel_wise'):p[k]=_core_bool(p[k],k)
        if p['max_chunk_size'] is not None:
            _core_int(p['max_chunk_size'],'max_chunk_size',1)
            if not p['channel_wise'] or not p['ransac']:raise ValueError('max_chunk_size needs channel-wise RANSAC')
        if p['reject_by_annotation'] not in (None,'omit'):raise ValueError('invalid reject_by_annotation')
        cls=_core_observed_reference();rng=_core_rng(p['random_state']);rng_before=_core_rng_dump(rng)
        ref=cls(y,{'ref_chs':list(p['ref_chs']),'reref_chs':list(p['reref_chs'])},
            ransac=p['ransac'],channel_wise=p['channel_wise'],max_chunk_size=p['max_chunk_size'],
            random_state=rng,reject_by_annotation=p['reject_by_annotation'],matlab_strict=False)
        ref._core_trace=[]
        with _core_warnings.catch_warnings(record=True) as caught:
            _core_warnings.simplefilter('always');ref.perform_reference(max_iterations=p['max_iterations'],interpolate_bads=False)
        if np.isinf(ref.raw.get_data()).any():raise ValueError('native reference produced infinity')
        outmodel=_core_reference_model(ref,'awaiting_final_interpolation')
        return _core_out(ref.raw.copy(),outmodel,parameters=p,rng_before=rng_before,rng_after=_core_rng_dump(rng),
            loop_trace=_core_copylib.deepcopy(ref._core_trace),initial_candidates=_core_copylib.deepcopy(ref.noisy_channels_original),
            cumulative_candidates=_core_copylib.deepcopy(ref.noisy_channels),unusable_channels=list(ref.unusable_channels),
            before_interpolation_candidates=list(ref.bad_before_interpolation),reference_signal_V=ref.reference_signal.copy(),
            warnings=[str(w.message) for w in caught],source_profile='pyprep_071')
    if op=='prep_reference_finalize':
        _core_kwargs(p,{})
        if not isinstance(model,dict) or model.get('kind')!='eeg_prep_reference_071_v1' or model.get('stage')!='awaiting_final_interpolation':raise ValueError('awaiting-final-interpolation model required')
        if model.get('author_source_sha256')!=_CORE_REFERENCE_SOURCE_SHA256 or _core_hashlib.sha256(_CorePath(_core_reference_module.__file__).read_bytes()).hexdigest()!=_CORE_REFERENCE_SOURCE_SHA256:raise ValueError('author source mismatch')
        check={k:v for k,v in model.items() if k!='state_hash'}
        if model.get('state_hash')!=_core_value_hash(check):raise ValueError('reference model state changed')
        y=_core_raw(x,allow_nan=True)
        if _core_raw_hash(y)!=model['data_hash']:raise ValueError('reference data/frame/montage/annotation mismatch')
        state=_core_copylib.deepcopy(model['state']);rng=_core_rng(state.pop('random_state'))
        ref=_core_reference_module.Reference.__new__(_core_reference_module.Reference)
        ref.__dict__.update(state);ref.raw=y;ref.random_state=rng
        before=_core_rng_dump(rng)
        with _core_warnings.catch_warnings(record=True) as caught:
            _core_warnings.simplefilter('always');ref.interpolate_bads()
        if not np.isfinite(ref.raw.get_data()).all():raise ValueError('final interpolation left nonfinite EEG')
        return _core_out(ref.raw.copy(),_core_reference_model(ref,'finalized'),
            interpolated_channels=list(ref.interpolated_channels),still_noisy_channels=list(ref.still_noisy_channels),
            reference_signal_V=ref.reference_signal_new.copy(),reference_correction_V=ref.reference_signal_new-ref.reference_signal,
            criterion_candidates=_core_copylib.deepcopy(ref.noisy_channels_after_interpolation),
            rng_before=before,rng_after=_core_rng_dump(rng),warnings=[str(w.message) for w in caught],source_profile='pyprep_071')
    raise ValueError('invalid operation')

"""RELAX v2.0.1 formula adapter. Copyright Neil Bailey et al.; GPL-3.0-or-later. Source commit 318300217bdb7ed47a19a892fed16690c5bb77b4."""
import numpy as np
import mne
from scipy.signal import butter, filtfilt
import hashlib, json
from numbers import Real

def _round(a):
    return np.floor(np.asarray(a) + 0.5).astype(int)

def _profile(p):
    if p not in ('relax_2_0_1', 'repaired_units_indices'):
        raise ValueError('profile=relax_2_0_1|repaired_units_indices')

def _real(a, name, ndim=None, finite=True):
    a = np.asarray(a)
    if a.dtype.kind not in 'iuf' or np.iscomplexobj(a):
        raise TypeError(name + ' needs real numeric array')
    a = np.asarray(a, float)
    if ndim is not None and a.ndim != ndim or (finite and (not np.isfinite(a).all())):
        raise ValueError(name + ' shape/finite')
    return a

def _bool(a, shape, name):
    a = np.asarray(a)
    if a.dtype.kind != 'b' or a.shape != shape:
        raise ValueError(name + ' requires boolean array ' + str(shape))
    return a

def _copy(x):
    if not isinstance(x, (mne.io.BaseRaw, mne.BaseEpochs)):
        raise TypeError('Raw/Epochs in V required')
    y = x.copy().load_data()
    a = y.get_data()
    if not a.size or not np.isfinite(a).all():
        raise ValueError('finite nonempty data required')
    return y

def _params(p, required, defaults):
    missing = set(required) - set(p)
    extra = set(p) - set(required) - set(defaults)
    if missing or extra:
        raise ValueError('missing=' + str(missing) + ' extra=' + str(extra))
    return {**defaults, **p}

def _out(x, **a):
    return {'data': x.copy(), 'model': None, 'artifacts': a}

def _runs(mask):
    d = np.diff(np.r_[False, np.asarray(mask, bool), False].astype(int))
    return list(zip(np.where(d == 1)[0], np.where(d == -1)[0]))

def _mean_shrink(a, h):
    c = np.r_[0.0, np.cumsum(a)]
    pos = np.arange(len(a))
    lo = np.maximum(0, pos - h)
    hi = np.minimum(len(a), pos + h + 1)
    return (c[hi] - c[lo]) / (hi - lo)

def _eye_weights_numeric(S, fs, eyes, raw_mask, profile):
    _profile(profile)
    S = _real(S, 'sources', 2)
    eyes = _bool(eyes, (len(S),), 'eyes')
    raw_mask = _bool(raw_mask, (S.shape[1],), 'raw_blink_mask')
    if not np.isfinite(fs) or fs <= 50:
        raise ValueError('fs must support 25Hz filter')
    b, a = butter(2, [0.5, 25], btype='bandpass', fs=fs)
    padlen = 3 * (max(len(a), len(b)) - 1)
    if S.shape[1] <= padlen:
        raise ValueError('insufficient samples for source filtfilt')
    h = int(_round(0.2 * fs))
    min_run = int(_round(_round(0.1 * fs) / (1000 / fs))) if profile == 'relax_2_0_1' else int(_round(0.1 * fs))
    weights = np.zeros_like(S)
    filtered = np.zeros_like(S)
    initial = np.zeros_like(S, dtype=bool)
    combined = initial.copy()
    for k in np.flatnonzero(eyes):
        q = filtfilt(b, a, S[k], padtype='odd', padlen=padlen)
        filtered[k] = q
        med = np.median(q)
        scaled_mad = 1.482602218505602 * np.median(abs(q - med))
        mask = abs(q - med) > 2 * scaled_mad
        initial[k] = mask
        starts = np.flatnonzero(np.diff(mask.astype(int)) == 1) + 1
        ends = np.flatnonzero(np.diff(mask.astype(int)) == -1)
        mask = mask | raw_mask
        if profile == 'relax_2_0_1':
            if len(starts):
                if not len(ends):
                    raise ValueError('author profile has unclosed initial IC blink run')
                if ends[0] < starts[0]:
                    ends = ends[1:]
                if not len(ends):
                    raise ValueError('author profile has no end after initial IC blink run')
                if ends[-1] < starts[-1]:
                    starts = starts[:-1]
                if len(starts) != len(ends):
                    raise ValueError('author IC blink endpoint mismatch')
                for st, en in zip(starts, ends):
                    if en - st < min_run:
                        mask[st:en + 1] = False
        else:
            for st, en in _runs(mask):
                if en - st < min_run:
                    mask[st:en] = False
        combined[k] = mask
        padded = mask.astype(float)
        for c in range(len(padded) - h - 2, -1, -1):
            if padded[c] == 1:
                padded[c:c + h + 1] = 1
        for c in range(h, len(padded)):
            if padded[c] == 1:
                padded[c - h:c + 1] = 1
        weights[k] = _mean_shrink(padded, h)
    return dict(eye_weights=weights, filtered_sources=filtered, ic_outlier_masks=initial, combined_masks=combined, minimum_run_samples=min_run, moving_mean_half_samples=h, profile=profile)

def _model_signature(x):
    projs = tuple(((p['desc'], int(p['kind']), bool(p['active']), tuple(p['data']['col_names']), hashlib.sha256(np.asarray(p['data']['data']).tobytes()).hexdigest()) for p in x.info['projs']))
    return (tuple(x.ch_names), tuple(x.get_channel_types()), tuple(x.info['bads']), int(x.info['custom_ref_applied']), projs)

def eeg_relax_eye_weights(op, x, model=None, **p):
    if op != 'eye_weights':
        raise ValueError('op=eye_weights')
    p = _params(p, ['eye_components', 'raw_blink_mask', 'component_id', 'reference_id'], {'profile': 'relax_2_0_1'})
    y = _copy(x)
    if not isinstance(y, mne.io.BaseRaw) or not isinstance(model, dict) or model.get('kind') != 'ica':
        raise TypeError('Raw and fitted ICA model required')
    ic = model['estimator']
    if model.get('signature') != _model_signature(y):
        raise ValueError('ICA channel/type/bads/reference/projector signature mismatch')
    if model.get('reference_id') != p['reference_id'] or model.get('sfreq') != y.info['sfreq'] or list(ic.ch_names) != [n for n, t in zip(y.ch_names, y.get_channel_types()) if t == 'eeg' and n not in y.info['bads']]:
        raise ValueError('ICA channel/reference/sampling mismatch')
    if p['component_id'] != _component_id(ic):
        raise ValueError('component identity mismatch')
    if ic.noise_cov is not None:
        raise ValueError('noise_cov=None required')
    S = ic.unmixing_matrix_ @ ic.pca_components_[:ic.n_components_] @ (y.get_data(picks=ic.ch_names) / ic.pre_whitener_)
    result = _eye_weights_numeric(S, y.info['sfreq'], p['eye_components'], p['raw_blink_mask'], p['profile'])
    return _out(y, **result, component_id=p['component_id'], reference_id=p['reference_id'])

def _identity_value(value):
    if isinstance(value, np.ndarray):
        if value.dtype.hasobject:
            raise TypeError('ICA identity cannot encode object arrays')
        if value.dtype.kind in 'fc' and (not np.isfinite(value).all()):
            raise ValueError('ICA identity parameters must be finite')
        return {'__ndarray__': {'dtype': value.dtype.str, 'shape': list(value.shape), 'sha256': hashlib.sha256(np.ascontiguousarray(value).tobytes()).hexdigest()}}
    if isinstance(value, np.generic):
        return _identity_value(value.item())
    if value is None or isinstance(value, (str, bool, int)):
        return value
    if isinstance(value, float):
        if not np.isfinite(value):
            raise ValueError('ICA identity parameters must be finite')
        return value
    if isinstance(value, (list, tuple)):
        return [_identity_value(v) for v in value]
    if isinstance(value, dict):
        if any((not isinstance(k, str) for k in value)):
            raise TypeError('ICA identity dictionary keys must be strings')
        return {k: _identity_value(value[k]) for k in sorted(value)}
    raise TypeError('Unsupported ICA identity parameter type: ' + type(value).__name__)

def _component_id(ic):
    metadata = dict(method=ic.method, n_components=int(ic.n_components_), fit_params=ic.fit_params, ch_names=ic.ch_names)
    h = hashlib.sha256(json.dumps(_identity_value(metadata), sort_keys=True, allow_nan=False).encode())
    for a in (ic.unmixing_matrix_, ic.mixing_matrix_, ic.pca_components_, ic.pre_whitener_, ic.pca_mean_):
        h.update(str(np.shape(a)).encode())
        h.update(np.asarray(a, dtype='<f8').tobytes())
    h.update('\x00'.join(ic.ch_names).encode())
    return h.hexdigest()

"""RELAX 2.0.1 numerical decision. GPL-3.0-or-later; volts, explicit axes."""
import numpy as np
import mne

def _number(v,name,lo=None,hi=None):
 if isinstance(v,(bool,np.bool_)) or not isinstance(v,(float,int,np.floating,np.integer)) or not np.isfinite(v) or (lo is not None and v<lo) or (hi is not None and v>hi):raise ValueError(name+' outside finite bounds')
 return float(v)

def _parameters(p,defaults,required):
 if set(p)-set(defaults) or set(required)-set(p):raise ValueError('unknown or missing parameters')
 return dict(defaults,**p)

def _input(x,model,kind):
 if model is not None:raise ValueError('decision does not accept a fitted model')
 if not isinstance(x,kind) or not x.preload:raise TypeError('preloaded '+kind.__name__+' required')
 if not x.ch_names or set(x.get_channel_types())!={'eeg'} or x.info['bads']:raise ValueError('current unmarked EEG channels only')
 if not np.isfinite(x.get_data()).all():raise ValueError('finite EEG required')

def channel_budget(mask,muscle_slopes,starts,window,n_samples,initial_count,channel_names,maximum=.1,extreme_fraction=.25,muscle_fraction=.5,muscle_threshold=-.31,profile='relax_2_0_1'):
 m=np.asarray(mask,bool).copy();sl=np.asarray(muscle_slopes,float);starts=np.asarray(starts,int)
 if m.shape!=sl.shape or m.shape!=(len(channel_names),len(starts)):raise ValueError('channel-window axes mismatch')
 if profile not in ('relax_2_0_1','repaired_units_indices'):raise ValueError('profile')
 C,E=m.shape;budget=int(np.floor(maximum*initial_count))-(initial_count-C)
 if budget<=0:return dict(extreme_bad=[],muscle_bad=[],initial_budget=budget,remaining_budget=budget,extreme_proportions=None,muscle_proportions=None)
 m[:,np.sum(m,axis=0)>budget]=False
 full=np.zeros((C,n_samples));covered=np.zeros(n_samples,bool)
 for e,s in enumerate(starts):
  if s<0 or s+window>n_samples:raise ValueError('diagnostic window out of range')
  covered[s:s+window]=True;full[m[:,e],s:s+window]=1
 if profile=='relax_2_0_1':
  flat=full.ravel(order='F');flat[np.flatnonzero(~covered)]=np.nan;full=flat.reshape(full.shape,order='F')
 else:full[:,~covered]=np.nan
 props=np.nanmean(full,axis=1);threshold=extreme_fraction;recommended=int(np.sum(props>threshold))
 if recommended>budget:threshold=np.percentile(props,100*(1-budget/C),method='hazen')
 reject=np.flatnonzero(props>threshold) if recommended else np.array([],int);remaining=np.setdiff1d(np.arange(C),reject);next_budget=budget-len(reject)
 muscle_bad=np.array([],int);mprops=None;mthreshold=muscle_fraction
 if next_budget>0:
  ignored=np.any(m[remaining],axis=0);scores=sl[remaining].copy();scores[:,ignored]=np.nan;mprops=np.sum(scores>muscle_threshold,axis=1)/E
  recommended_m=int(np.sum(mprops>muscle_fraction))
  if recommended_m>next_budget:mthreshold=np.sort(mprops)[::-1][next_budget-1]
  if recommended_m:
   selected=mprops>=mthreshold
   if np.sum(selected)>next_budget:selected=mprops>mthreshold
   muscle_bad=remaining[selected]
 return dict(extreme_bad=[channel_names[k] for k in reject],muscle_bad=[channel_names[k] for k in muscle_bad],initial_budget=budget,remaining_budget=next_budget-len(muscle_bad),extreme_proportions=props,muscle_proportions=mprops,extreme_threshold=threshold,muscle_threshold=mthreshold,profile=profile)

def eeg_channel_rejection_budget(op,x,model=None,**p):
 if op!='relax_budget':raise ValueError('operation=relax_budget')
 _input(x,model,mne.io.BaseRaw)
 p=_parameters(p,dict(channel_epoch_mask=None,muscle_slopes=None,window_starts=None,window_samples=None,original_channels=None,maximum=.1,extreme_fraction=.25,muscle_fraction=.5,muscle_threshold=-.31,profile='relax_2_0_1'),['channel_epoch_mask','muscle_slopes','window_starts','window_samples','original_channels'])
 m=np.asarray(p['channel_epoch_mask']);s=np.asarray(p['muscle_slopes']);starts=np.asarray(p['window_starts']);win=p['window_samples'];names=p['original_channels']
 if m.dtype.kind!='b' or m.ndim!=2 or m.shape!=(len(x.ch_names),len(starts)) or m.shape[1]<1:raise ValueError('boolean channel x epoch mask required')
 if s.shape!=m.shape or s.dtype.kind not in 'fiu' or not np.isfinite(s).all():raise ValueError('finite channel x epoch slopes required')
 if starts.ndim!=1 or starts.dtype.kind not in 'iu' or np.any(starts[1:]<=starts[:-1]):raise ValueError('strictly increasing integer window starts required')
 if isinstance(win,(bool,np.bool_)) or not isinstance(win,(int,np.integer)) or win<1 or np.any(starts<0) or np.any(starts>x.n_times-win):raise ValueError('window samples outside Raw')
 if not isinstance(names,(list,tuple)) or not names or any(not isinstance(n,str) or not n for n in names) or len(set(names))!=len(names) or not set(x.ch_names)<=set(names):raise ValueError('unique original channel names containing current channels required')
 for k in ['maximum','extreme_fraction','muscle_fraction']:_number(p[k],k,0,1)
 _number(p['muscle_threshold'],'muscle_threshold')
 out=channel_budget(m,s,starts,win,x.n_times,len(names),x.ch_names,**{k:p[k] for k in ['maximum','extreme_fraction','muscle_fraction','muscle_threshold','profile']})
 out.update(channel_names=list(x.ch_names),original_channels=list(names),window_starts=starts.copy(),window_samples=int(win),axis_order='channel, epoch')
 return dict(data=x.copy(),model=None,artifacts=out)

"""RELAX 2.0.1 numerical decision. GPL-3.0-or-later; volts, explicit axes."""
import numpy as np
import mne

def _number(v,name,lo=None,hi=None):
 if isinstance(v,(bool,np.bool_)) or not isinstance(v,(float,int,np.floating,np.integer)) or not np.isfinite(v) or (lo is not None and v<lo) or (hi is not None and v>hi):raise ValueError(name+' outside finite bounds')
 return float(v)

def _parameters(p,defaults,required):
 if set(p)-set(defaults) or set(required)-set(p):raise ValueError('unknown or missing parameters')
 return dict(defaults,**p)

def _input(x,model,kind):
 if model is not None:raise ValueError('decision does not accept a fitted model')
 if not isinstance(x,kind) or not x.preload:raise TypeError('preloaded '+kind.__name__+' required')
 if not x.ch_names or set(x.get_channel_types())!={'eeg'} or x.info['bads']:raise ValueError('current unmarked EEG channels only')
 if not np.isfinite(x.get_data()).all():raise ValueError('finite EEG required')

def muscle_epoch_rejection(slopes,threshold=-.31,maximum=.5):
 s=np.asarray(slopes,float)
 if s.ndim!=2 or not np.isfinite(s).all():raise ValueError('finite epoch x channel slopes required')
 mask=np.any(s>threshold,axis=1);severity=np.sum(np.maximum(s-threshold,0),axis=1);cut=0.
 if mask.mean()>maximum:cut=float(np.percentile(severity,100*(1-maximum),method='hazen'));mask=severity>cut
 return {'epoch_mask':mask,'severity':severity,'severity_threshold':cut,'maximum_fraction':maximum}

def eeg_muscle_trial_decision(op,x,model=None,**p):
 if op!='relax_muscle_trials':raise ValueError('operation=relax_muscle_trials')
 _input(x,model,mne.BaseEpochs)
 p=_parameters(p,dict(slopes=None,trial_ids=None,threshold=-.31,maximum=.5),['slopes','trial_ids'])
 s=np.asarray(p['slopes']);ids=p['trial_ids']
 if not len(x) or s.shape!=(len(x),len(x.ch_names)) or s.dtype.kind not in 'fiu' or not np.isfinite(s).all():raise ValueError('nonempty finite epoch x channel slopes required')
 if not isinstance(ids,(list,tuple)) or len(ids)!=len(x) or any(not isinstance(v,str) or not v for v in ids) or len(set(ids))!=len(ids):raise ValueError('unique Trial ID per current epoch required')
 _number(p['threshold'],'threshold');_number(p['maximum'],'maximum',0,1)
 out=muscle_epoch_rejection(s,p['threshold'],p['maximum']);out.update(trial_ids=list(ids),channel_names=list(x.ch_names),epoch_selection=x.selection.copy(),events=x.events.copy(),axis_order='epoch, channel')
 return dict(data=x.copy(),model=None,artifacts=out)
